package com.nyayaconnect.auth;
import com.nyayaconnect.common.*; import com.nyayaconnect.security.*; import com.nyayaconnect.user.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.*;
public class RegisterServlet extends HttpServlet { private UserService users; public void init(){users=SpringAccess.bean(getServletContext(),UserService.class);}
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{try{Map<?,?> b=Json.MAPPER.readValue(req.getInputStream(),Map.class);String name=get(b,"name").trim();String email=get(b,"email").trim().toLowerCase();String pw=get(b,"password");UserRole role=UserRole.valueOf(get(b,"role","CLIENT").toUpperCase());if(role==UserRole.ADMIN)throw new IllegalArgumentException("Admin accounts are provisioned by operators.");if(name.length()<2)throw new IllegalArgumentException("Name is required.");String bar=role==UserRole.LAWYER?get(b,"barCouncilNumber").trim():"";UUID id=users.register(name,email,pw,role,bar);Api.json(res,201,Map.of("id",id,"message",role==UserRole.LAWYER?"Registration successful. Your lawyer profile is pending administrator verification.":"Registration successful."));}catch(IllegalArgumentException e){Api.error(res,400,"VALIDATION_ERROR",e.getMessage());}catch(Exception e){Api.error(res,500,"REGISTRATION_FAILED","Registration could not be completed.");}}
 private static String get(Map<?,?> m,String k){return get(m,k,"");} private static String get(Map<?,?> m,String k,String d){Object v=m.get(k);return v==null?d:String.valueOf(v);}
}
